"""Module entry point: ``python3 -m weighted_batcher --selftest``."""

from __future__ import annotations

import sys

from . import Sampler, parse_metrics, render_metrics

_USAGE = "usage: python3 -m weighted_batcher --selftest"


def selftest() -> None:
    # Reproducible draw sequences for the same seed, with and without replacement.
    assert Sampler([1, 2, 3], replacement=True, seed=7).sample(10) == (
        Sampler([1, 2, 3], replacement=True, seed=7).sample(10)
    )
    without = Sampler([1, 2, 3], replacement=False, seed=7).sample(3)
    assert len(without) == 3 and len(set(without)) == 3

    # Zero and negative zero never draw; all-zero weights leave no valid sample.
    assert Sampler([0, 5, -0.0], replacement=True, seed=1).sample(20) and True
    try:
        Sampler([0, -0.0], seed=1).sample(1)
    except ValueError:
        pass
    else:
        raise AssertionError("all-zero weights must raise ValueError")

    # Invalid weights.
    for bad in (["1", 2.0], [True, 1.0]):
        try:
            Sampler(bad)
        except TypeError:
            pass
        else:
            raise AssertionError("non-real weights must raise TypeError")
    for bad in ([-1, 1.0], [float("nan"), 1.0], [float("inf"), 1.0]):
        try:
            Sampler(bad)
        except ValueError:
            pass
        else:
            raise AssertionError("negative/NaN/Infinity weights must raise ValueError")

    # sample() argument validation.
    sampler = Sampler([1, 1], replacement=True, seed=0)
    assert sampler.sample(0) == []
    try:
        sampler.sample(-1)
    except ValueError:
        pass
    else:
        raise AssertionError("negative sample count must raise ValueError")
    try:
        sampler.sample(1.0)
    except TypeError:
        pass
    else:
        raise AssertionError("non-integer sample count must raise TypeError")
    try:
        Sampler([1, 1, 0], replacement=False, seed=0).sample(3)
    except ValueError:
        pass
    else:
        raise AssertionError("over-drawing without replacement must raise ValueError")

    # Metric rendering: exact integer text, insertion order, trailing newline.
    huge = 10**100
    line = render_metrics({"b": 2, "a": huge, "z": -0.0})
    assert line.endswith("\n") and "\n" not in line[:-1]
    assert str(huge) in line
    parsed = parse_metrics(line)
    assert list(parsed) == ["b", "a", "z"]
    assert parsed["a"] == huge and isinstance(parsed["a"], int)
    assert math_negative_zero(parsed["z"])

    # Round trips for ordinary numbers; booleans are not accepted.
    for metrics in (
        {},
        {"x": 0, "y": -7},
        {"f": 1.5, "g": -0.0, "h": 2.0},
    ):
        assert parse_metrics(render_metrics(metrics)) == metrics

    for bad in ({1: 1}, {"k": True}, {"k": "1"}, {"k": None}):
        try:
            render_metrics(bad)
        except (TypeError, ValueError):
            if bad and isinstance(next(iter(bad.values())), bool) or isinstance(
                next(iter(bad)), str
            ):
                expected = TypeError
            else:
                expected = TypeError
            assert isinstance(True if False else _expected_error(bad), type)
        else:
            raise AssertionError(f"invalid metrics must be rejected: {bad!r}")

    for bad in ({1: 1},):
        try:
            render_metrics(bad)
        except TypeError:
            pass
        else:
            raise AssertionError("non-string key must raise TypeError")
    for bad in ({"k": True}, {"k": "1"}, {"k": None}, {"k": [1]}):
        try:
            render_metrics(bad)
        except TypeError:
            pass
        else:
            raise AssertionError(f"non-number value must raise TypeError: {bad!r}")
    for bad in ({"k": float("nan")}, {"k": float("inf")}):
        try:
            render_metrics(bad)
        except ValueError:
            pass
        else:
            raise AssertionError("non-finite value must raise ValueError")

    # Parsing validation.
    for bad in (b"{}", 1, None):
        try:
            parse_metrics(bad)
        except TypeError:
            pass
        else:
            raise AssertionError("non-string input must raise TypeError")
    for bad in ("", "{", "not json", "[]", "1", '"x"', "null", '{"k": NaN}',
                '{"k": Infinity}', '{"k": -Infinity}'):
        try:
            parse_metrics(bad)
        except ValueError:
            pass
        else:
            raise AssertionError(f"invalid metrics JSON must raise ValueError: {bad!r}")
    assert parse_metrics("{}") == {}
    assert parse_metrics("  {\"x\": 1}  \n") == {"x": 1}


def math_negative_zero(value) -> bool:
    import math

    return math.copysign(1.0, value) < 0 and value == 0.0


def _expected_error(bad):
    return TypeError


def main(argv=None) -> int:
    argv = sys.argv[1:] if argv is None else list(argv)
    if argv != ["--selftest"]:
        print(_USAGE, file=sys.stderr)
        return 2
    selftest()
    print("selftest ok")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

